import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Widget languages, HA sources and Climate","description":"DE/EN/FR, attribute sources, units and optional Climate controls from Studio 0.1.296.","frontmatter":{"title":"Widget languages, HA sources and Climate","description":"DE/EN/FR, attribute sources, units and optional Climate controls from Studio 0.1.296."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/ha-quellen-climate.md","filePath":"en/projects/grafik-visual-studio/ha-quellen-climate.md","lastUpdated":1792852622000}'),s={name:"en/projects/grafik-visual-studio/ha-quellen-climate.md"};function n(o,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="widget-languages-ha-sources-and-climate" tabindex="-1">Widget languages, HA sources and Climate <a class="header-anchor" href="#widget-languages-ha-sources-and-climate" aria-label="Permalink to &quot;Widget languages, HA sources and Climate&quot;">​</a></h1><p>From <strong>Studio 0.1.296</strong>, the remaining <strong>62 widget types</strong> (Special, gauges, data flow and seven bundled packages) offer widget properties and runtime messages in <strong>DE/EN/FR</strong>. The overall Studio shell remains DE/EN. <a href="/projects/grafik-visual-studio/ha-quellen-climate">Deutsch</a> · <a href="/fr/projects/grafik-visual-studio/ha-quellen-climate">Français</a>.</p><h2 id="choose-a-language" tabindex="-1">Choose a language <a class="header-anchor" href="#choose-a-language" aria-label="Permalink to &quot;Choose a language&quot;">​</a></h2><p><strong>Widget language</strong> in project settings defines the default. The widget group with the same name may override it. Calendar+, Energy, Industrial, Printer, Solar, Technic and Weather/Heating work with existing package versions. User labels, entity IDs and saved keys are not translated or rewritten.</p><h2 id="check-an-ha-source" tabindex="-1">Check an HA source <a class="header-anchor" href="#check-an-ha-source" aria-label="Permalink to &quot;Check an HA source&quot;">​</a></h2><p>Bound read sources offer the initially disabled <strong>HA sources and units</strong> group. An empty attribute reads the state; otherwise enter an attribute. <strong>Check source</strong> refreshes the value, discovers attribute names and reports its unit, missing data or incompatible conversion. Structured values receive a JSON structure hint. The attribute must match the widget’s expected schema.</p><p>Automatic conversion is optional. For an Energy source it replaces the legacy factor without deleting the setting. Fixed displays/calculations follow their widget unit: Solar W/°C/%, battery energy kWh, Climate native temperature unit. Their target-unit field is locked. Configurable sources support compatible power, energy, temperature, price, length, volume, speed and pressure units. Missing metadata or incompatible units result in unknown values. Native HA write targets remain unchanged.</p><p>Energy can read selected numeric Recorder attributes; missing attributes create gaps. Different history attributes of one entity require separate history widgets. Offset-based C/F conversion is not applied to Energy history. The separate thermostat history view retains its native HA sources; source options affect its live display. Recorder is not the complete native Energy dashboard or long-term statistics.</p><h2 id="climate-controls" tabindex="-1">Climate controls <a class="header-anchor" href="#climate-controls" aria-label="Permalink to &quot;Climate controls&quot;">​</a></h2><p>Enable <strong>Climate controls</strong> on <strong>Technic Thermostat – Temperature</strong>, then select the required options:</p><ul><li>Heating/cooling range with two targets and a shared Apply button.</li><li>HVAC mode and preset.</li><li>Fan mode, vertical and horizontal swing.</li><li>Target humidity and power.</li></ul><p>Runtime only offers capabilities/values reported by the device. Limits and step sizes are rechecked server-side. The existing single target remains available; range-only devices use the range controls. Editor mode, read-only settings and unavailable states disable controls. Enlarge widgets with many controls; the additional section scrolls in small widgets.</p><p>New groups start disabled. Existing projects, groups and factors remain valid. A successful service call means submission to HA, not physical confirmation. Real devices, Ingress/Companion, external embedding and notification delivery require installation testing.</p><p><a href="https://www.home-assistant.io/integrations/climate/" target="_blank" rel="noreferrer">HA Climate</a> · <a href="https://developers.home-assistant.io/docs/core/entity/climate/" target="_blank" rel="noreferrer">Device capabilities</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Audit report</a></p>',14)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
